import 'dart:math' as math;

import 'who_growth_data.g.dart';

/// 20d / 20i: the WHO Child Growth Standards, hard-coded (who_growth_data.g.dart, generated by
/// tool/who_growth_data.py). "Thấp" and "Cao" are the 3rd and 97th percentiles — the edges of the
/// "khoảng bình thường" band — and "Trung vị" the median, as on the WHO percentile tables.
enum GrowthMeasure { weight, length }

/// Where a measurement sits against the band.
enum GrowthBand { below, normal, above }

typedef GrowthRange = ({double low, double median, double high});

/// One row of the 20i table: an age, in weeks (0–13) or months (0–24).
typedef GrowthAge = ({int value, bool weeks, int days});

abstract final class WhoGrowth {
  /// z of the 3rd / 97th percentile.
  static const zBand = 1.880793608;

  /// The WHO tables stop at 5 years.
  static const maxDays = 1856;

  static List<double> _table(GrowthMeasure m, {required bool boy}) =>
      switch ((m, boy)) {
        (GrowthMeasure.weight, true) => whoWeightBoys,
        (GrowthMeasure.weight, false) => whoWeightGirls,
        (GrowthMeasure.length, true) => whoLengthBoys,
        (GrowthMeasure.length, false) => whoLengthGirls,
      };

  /// L, M, S at [ageDays], interpolated between table rows; null outside 0–5 years.
  static (double, double, double)? lms(
    GrowthMeasure m, {
    required bool boy,
    required int ageDays,
  }) {
    if (ageDays < 0 || ageDays > maxDays) return null;
    final t = _table(m, boy: boy);
    final rows = t.length ~/ 4;
    var lo = 0;
    var hi = rows - 1;
    while (hi - lo > 1) {
      final mid = (lo + hi) ~/ 2;
      if (t[mid * 4] <= ageDays) {
        lo = mid;
      } else {
        hi = mid;
      }
    }
    final d0 = t[lo * 4];
    final d1 = t[hi * 4];
    final f = d1 == d0 ? 0.0 : ((ageDays - d0) / (d1 - d0)).clamp(0.0, 1.0);
    double at(int i) => t[lo * 4 + i] + (t[hi * 4 + i] - t[lo * 4 + i]) * f;
    return (at(1), at(2), at(3));
  }

  static double _value((double, double, double) lms, double z) {
    final (l, m, s) = lms;
    return l == 0 ? m * math.exp(s * z) : m * math.pow(1 + l * s * z, 1 / l);
  }

  /// The band at [ageDays]: 3rd percentile, median, 97th percentile.
  static GrowthRange? range(
    GrowthMeasure m, {
    required bool boy,
    required int ageDays,
  }) {
    final p = lms(m, boy: boy, ageDays: ageDays);
    if (p == null) return null;
    return (
      low: _value(p, -zBand),
      median: _value(p, 0),
      high: _value(p, zBand),
    );
  }

  /// The measurement's z-score (WHO LMS method).
  static double? zScore(
    GrowthMeasure m, {
    required bool boy,
    required int ageDays,
    required double value,
  }) {
    final p = lms(m, boy: boy, ageDays: ageDays);
    if (p == null || value <= 0) return null;
    final (l, med, s) = p;
    return l == 0
        ? math.log(value / med) / s
        : (math.pow(value / med, l) - 1) / (l * s);
  }

  static GrowthBand? band(
    GrowthMeasure m, {
    required bool boy,
    required int ageDays,
    required double value,
  }) {
    final z = zScore(m, boy: boy, ageDays: ageDays, value: value);
    if (z == null) return null;
    if (z < -zBand) return GrowthBand.below;
    if (z > zBand) return GrowthBand.above;
    return GrowthBand.normal;
  }

  /// 20i rows: "Mới sinh", 1–13 tuần; or "Mới sinh", 1–24 tháng.
  static List<GrowthAge> ages({required bool weeks}) => [
    if (weeks)
      for (var w = 0; w <= 13; w++) (value: w, weeks: true, days: w * 7)
    else
      for (var mo = 0; mo <= 24; mo++)
        (value: mo, weeks: false, days: (mo * 30.4375).round()),
  ];

  /// The row a baby of [ageDays] belongs to (the last one not after their age).
  static int rowFor(List<GrowthAge> ages, int ageDays) {
    var i = 0;
    for (var k = 0; k < ages.length; k++) {
      if (ages[k].days <= ageDays) i = k;
    }
    return i;
  }
}
